def minimizeXor(num1: int, num2: int) -> int:
    target_bits = bin(num2).count('1')
    curr_bits = bin(num1).count('1')
    res = num1
    for i in range(32):
        if curr_bits > target_bits and (res & (1 << i)):
            res ^= (1 << i)
            curr_bits -= 1
        elif curr_bits < target_bits and not (res & (1 << i)):
            res |= (1 << i)
            curr_bits += 1
    return res

